sys_script_include.script:
var BillingUtils = Class.create();
BillingUtils.prototype = {
    initialize: function() {
    },
	//Calculate the total billing amount for a patient.
	gettotalamount: function(id)
	{
		var patientamount = new GlideRecord('u_billing');
		patientamount.addQuery("u_patient_id",id);
		patientamount.query();
		if(patientamount.next())
		{
			return patientamount;
		}
		else{
			return "No amount";
		}
	},
	//Check if a billing record is overdue. 
	getstatus: function(billingid)
	{
		var billstatus = new GlideRecord('u_billing');
		billstatus.addQuery('number',billingid);
		billstatus.query();
		if(billstatus.next())
		{
			if(billstatus.u_status == "overdue")
			{
				return true;
			}
			else{
				return false;
			}

		}
		else{
			return "No Record"
		}
	},
	//Fetch billing details by ID.
	getbillingdetails: function(billingid)
	{
		var details = new GlideRecord('u_billing');
		details.addQuery('number',billingid);
		details.query();
		if(details.next())
		{
			return details;
		}
		else{
			return "No Details Found";
		}
	},
	//Fetch billing records by patient ID.
	getdetailsbypatient: function(patientid)
	{
		var details = new GlideRecord('u_billing');
		details.addQuery('u_patient_id',patientid);
		details.query();
		return details;
	},

    type: 'BillingUtils'
};
